    {"name":"edit","arguments":{"path":"shipping/zones.py","old":"def normalise(postal_code):\n    \"\"\"The postal code without spaces, in upper case.\"\"\"\n    raise NotImplementedError\n","new":"def normalise(postal_code):\n    \"\"\"The postal code without spaces, in upper case.\"\"\"\n    return postal_code.replace(\" \", \"\").upper()\n"}},
    {"name":"edit","arguments":{"path":"shipping/zones.py","old":"def lookup(postal_code):\n    \"\"\"`(zone, remote)` for a postal code as the customer typed it.\"\"\"\n    raise NotImplementedError\n","new":"def lookup(postal_code):\n    \"\"\"`(zone, remote)` for a postal code as the customer typed it.\"\"\"\n    code = normalise(postal_code)\n    matches = [entry for entry in rates.PREFIXES if code.startswith(entry[0])]\n    if not matches:\n        raise QuoteError(f\"Unknown postal code: {postal_code}\")\n    _, zone, remote = max(matches, key=lambda entry: len(entry[0]))\n    return zone, remote\n"}},
    {"name":"edit","arguments":{"path":"shipping/weights.py","old":"def volumetric_g(item):\n    \"\"\"The volumetric weight of the whole line, in grams.\"\"\"\n    raise NotImplementedError\n","new":"def volumetric_g(item):\n    \"\"\"The volumetric weight of the whole line, in grams.\"\"\"\n    a, b, c = item[\"dims_cm\"]\n    return ((a * b * c + 4) // 5) * item[\"qty\"]\n"}},
    {"name":"edit","arguments":{"path":"shipping/weights.py","old":"def billable_g(items):\n    \"\"\"The billable weight of the shipment, in grams.\"\"\"\n    raise NotImplementedError\n","new":"def billable_g(items):\n    \"\"\"The billable weight of the shipment, in grams.\"\"\"\n    actual = sum(item[\"qty\"] * item[\"weight_g\"] for item in items)\n    volumetric = sum(volumetric_g(item) for item in items)\n    weight = max(actual, volumetric)\n    return ((weight + 499) // 500) * 500\n"}},
    {"name":"edit","arguments":{"path":"shipping/surcharges.py","old":"def surcharges(items, base, remote):\n    \"\"\"The surcharges of a shipment as a dict; a surcharge of zero is left out.\"\"\"\n    raise NotImplementedError\n","new":"def surcharges(items, base, remote):\n    \"\"\"The surcharges of a shipment as a dict; a surcharge of zero is left out.\"\"\"\n    result = {}\n    if remote and base:\n        result[\"remote\"] = (base * rates.REMOTE_PERCENT * 2 + 100) // 200\n    fragile = min(sum(item[\"qty\"] for item in items if item.get(\"fragile\", False)) * rates.FRAGILE_PER_UNIT, rates.FRAGILE_CAP)\n    if fragile:\n        result[\"fragile\"] = fragile\n    if any(any(side > rates.OVERSIZE_SIDE_CM for side in item[\"dims_cm\"]) or item[\"weight_g\"] > rates.OVERSIZE_WEIGHT_G for item in items):\n        result[\"oversize\"] = rates.OVERSIZE_FEE\n    return result\n"}},
    {"name":"edit","arguments":{"path":"shipping/quote.py","old":"def quote(order):\n    \"\"\"The quote for `order`, as described in the README.\"\"\"\n    raise NotImplementedError\n","new":"def quote(order):\n    \"\"\"The quote for `order`, as described in the README.\"\"\"\n    items = order[\"items\"]\n    if not items:\n        raise QuoteError(\"An order must contain items\")\n    for item in items:\n        qty = item[\"qty\"]\n        if not isinstance(qty, int) or isinstance(qty, bool) or qty <= 0:\n            raise QuoteError(\"Quantity must be a positive integer\")\n        for value in (item[\"weight_g\"], *item[\"dims_cm\"]):\n            if not isinstance(value, int) or isinstance(value, bool) or value <= 0:\n                raise QuoteError(\"Weight and dimensions must be positive integers\")\n    service = order[\"service\"]\n    if service not in (\"standard\", \"express\"):\n        raise QuoteError(\"Unknown service\")\n    zone, remote = zones.lookup(order[\"destination\"])\n    tariff = rates.ZONES[zone]\n    billable = weights.billable_g(items)\n    base = tariff[\"first_500\"] + ((billable - 500) // 500) * tariff[\"per_extra_500\"]\n    if service == \"express\":\n        if zone in rates.EXPRESS_UNAVAILABLE_IN:\n            raise QuoteError(\"Express is unavailable in this zone\")\n        base = (base * 3 + 1) // 2\n    elif sum(item[\"qty\"] * item[\"price\"] for item in items) >= rates.FREE_SHIPPING_FROM and not remote:\n        base = 0\n    coupon = order.get(\"coupon\")\n    if coupon is not None:\n        if coupon == \"SHIP50\":\n            base //= 2\n        elif coupon == \"FREESHIP\":\n            if not remote:\n                base = 0\n        else:\n            raise QuoteError(\"Unknown coupon\")\n    fees = surcharges.surcharges(items, base, remote)\n    return {\"zone\": zone, \"billable_g\": billable, \"base\": base, \"surcharges\": fees, \"total\": base + sum(fees.values())}\n"}},
